# ---------------------------------------------------------------------------
# GENERATED BY AN LLM: Claude (Anthropic), 2026-11-22: summary table and figures for
# the tile coding / RBF tuning results.
# Updated 2026-11-23: for the after-fix runs (one figure per case, LLM footer on every
# figure); later, case numbers removed from the figure titles and the default input
# folders set to the renamed ones.
# Updated 2026-11-26: new --ieee option that draws the figures at print size for a
# two-column IEEE paper (see "IEEE mode" below).
# The chosen values marked on the figures (CHOSEN below) are Jagjit's decisions.
# ---------------------------------------------------------------------------
# Turns the training CSVs into one summary table and one figure per case.
#
#   python3 tools/plot_results.py [--in results/precode-merge-results]
#                                 [--bench-dir "results/prev runs"] [--out results/figures]
#                                 [--ieee]
#
# --ieee: figures at print size for a two-column IEEE paper, one column (3.5 in) or both
# columns (7.16 in) wide, with 8 pt text and no title or subtitle (the LaTeX caption
# carries them), saved as PDF and 300 dpi PNG in results/figures/ieee/ unless --out is given.
#
# Input: CSVs written by save_csv() (policy,episode,seconds,end_reason). One file
# holds several runs back to back; a run starts where episode == 0. If the same
# run appears twice in a row (identical name and data) the copy is dropped.
# When several files share a prefix (e.g. a rerun), the newest one is used.
# Sweep values are read from the file names (e.g. tc-alpha-tune-0.6_<date>.csv).
#
# Output:
#   summary.csv  one row per condition (mean and seed range of the first and the
#                last 5,000 episodes, episodes to reach 30 s, out-of-bounds rate)
#   fig*.png     the figures
import argparse
import csv
import glob
import logging
import os

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np

# ---- what to plot ---------------------------------------------------------
BENCHMARK_PREFIX = "benchmarks"
EARLY = 5000          # "first 5k" window
LATE = 5000           # "last 5k" window
BLOCK = 1000          # learning curves: average of every 1,000 episodes
SPEED_LEVEL = 30.0    # learning speed: episodes until the moving average reaches this
SPEED_WINDOW = 500    # moving-average window for the speed metric

# ---- colours (validated categorical slots 1-3, light mode) -----------------
SERIES = ["#2a78d6", "#eb6834", "#1baf7a"]
INK = "#0b0b0b"
INK2 = "#52514e"
MUTED = "#898781"
GRID = "#e1e0d9"
AXIS = "#c3c2b7"
SURFACE = "#fcfcfb"

logging.getLogger("matplotlib.font_manager").setLevel(logging.ERROR)  # quiet missing-font fallbacks
plt.rcParams.update({
    "font.family": ["Inter", "Helvetica Neue", "Helvetica", "Arial", "DejaVu Sans"],
    "font.size": 10,
    "axes.edgecolor": AXIS,
    "axes.labelcolor": INK2,
    "axes.titlecolor": INK,
    "axes.facecolor": SURFACE,
    "figure.facecolor": SURFACE,
    "xtick.color": MUTED,
    "ytick.color": MUTED,
    "xtick.labelcolor": INK2,
    "ytick.labelcolor": INK2,
    "axes.spines.top": False,
    "axes.spines.right": False,
    "legend.frameon": False,
})

# ---- IEEE mode (--ieee) ---------------------------------------------------------
MODE = {"ieee": False}
COLUMN_W, TEXT_W = 3.5, 7.16   # IEEE conference column width and text width, inches
IEEE_SCALE = 0.8               # font sizes and line widths relative to the screen figures


def k(x):
    """A font size or line width of the screen figures, for the current mode."""
    return x * IEEE_SCALE if MODE["ieee"] else x


def ka(s):
    """A scatter marker area of the screen figures, for the current mode."""
    return s * 0.45 if MODE["ieee"] else s


def set_ieee():
    MODE["ieee"] = True
    plt.rcParams.update({"font.size": 8, "axes.labelsize": 8, "xtick.labelsize": 7, "ytick.labelsize": 7,
                         "legend.fontsize": 7, "axes.linewidth": 0.6})


def figsize(kind="column"):
    """kind: "column" (one IEEE column) or "full" (both columns); the screen size otherwise."""
    if not MODE["ieee"]:
        return (8, 4.5)
    return (COLUMN_W, 2.45) if kind == "column" else (TEXT_W, 2.45)


def save_ieee(fig, path, left=0.16, right=0.98, bottom=0.2, top=0.97, wspace=0.08, hspace=None):
    """IEEE mode: no title or subtitle, a small LLM credit, saved as PDF and 300 dpi PNG."""
    fig.subplots_adjust(left=left, right=right, bottom=bottom, top=top, wspace=wspace, hspace=hspace)
    fig.canvas.draw()  # place the credit just below the lowest drawn element, flush with the right edge
    r = fig.canvas.get_renderer()
    boxes = [a.get_tightbbox(r) for a in fig.axes] + [t.get_window_extent(r) for t in fig.texts]
    boxes = [b for b in boxes if b is not None and b.width > 0]
    fig.text(max(b.x1 for b in boxes) / fig.bbox.width, (min(b.y0 for b in boxes) - 3) / fig.bbox.height,
             "Visualization generated by an LLM (Claude, Anthropic)", ha="right", va="top", fontsize=5,
             color=MUTED)
    base = os.path.splitext(path)[0]
    fig.savefig(base + ".pdf", bbox_inches="tight", pad_inches=0.02)
    fig.savefig(base + ".png", dpi=300, bbox_inches="tight", pad_inches=0.02)
    plt.close(fig)
    print("wrote", base + ".pdf and .png")


# ---- loading ----------------------------------------------------------------
def read_runs(path):
    """Return [(name, seconds array, end_reason list)] for every run in the file."""
    runs = []
    with open(path) as f:
        reader = csv.reader(f)
        next(reader)
        for name, ep, sec, reason in reader:
            if ep == "0":
                runs.append([name, [], []])
            runs[-1][1].append(float(sec))
            runs[-1][2].append(reason)
    out = []
    for name, secs, reasons in runs:
        secs = np.array(secs)
        if out and out[-1][0] == name and np.array_equal(out[-1][1], secs):
            continue  # same run written twice
        out.append((name, secs, reasons))
    return out


def load(in_dir, prefix):
    files = sorted(glob.glob(os.path.join(in_dir, prefix + "_*.csv")))
    if not files:
        raise FileNotFoundError(f"no CSV starting with {prefix}_ in {in_dir}")
    return read_runs(files[-1])  # file names end in a timestamp, so the last is the newest


def sweep_values(in_dir, prefix):
    """Values of a sweep, read from file names '<prefix>-<value>_<timestamp>.csv', in numeric order."""
    vals = set()
    for f in glob.glob(os.path.join(in_dir, prefix + "-*_*.csv")):
        vals.add(os.path.basename(f)[len(prefix) + 1:].split("_")[0])
    return sorted(vals, key=float)


def benchmarks(in_dir):
    return {name: secs.mean() for name, secs, _ in load(in_dir, BENCHMARK_PREFIX)}


# ---- metrics ----------------------------------------------------------------
def blocks(secs, size=BLOCK):
    n = len(secs) // size
    return secs[: n * size].reshape(n, size).mean(axis=1)


def episodes_to_reach(secs, level=SPEED_LEVEL, window=SPEED_WINDOW):
    avg = np.convolve(secs, np.ones(window) / window, mode="valid")
    hit = np.nonzero(avg >= level)[0]
    return int(hit[0] + window) if len(hit) else None


def summarize(runs):
    early = [s[:EARLY].mean() for _, s, _ in runs]
    late = [s[-LATE:].mean() for _, s, _ in runs]
    speed = [episodes_to_reach(s) for _, s, _ in runs]
    out_pct = [100.0 * r.count("out") / len(r) for _, _, r in runs]
    return early, late, speed, out_pct


# ---- drawing helpers ----------------------------------------------------------
def style_axes(ax):
    ax.grid(axis="y", color=GRID, linewidth=k(0.6))
    ax.set_axisbelow(True)
    ax.tick_params(length=0)


BENCH_LABELS = {"HandCoded": "Hand-coded", "Random": "Random", "AlwaysHold": "Always hold"}


def reference_lines(ax, bench, names=("HandCoded", "Random"), label=True):
    """Dashed line per benchmark; label=False leaves the labels to the caller."""
    labels = BENCH_LABELS
    for name in names:
        y = bench[name]
        ax.axhline(y, color=MUTED, linewidth=k(1.0), linestyle=(0, (4, 3)), zorder=1)
        if not label:
            continue
        ax.annotate(f"{labels[name]} {y:.1f} s", xy=(0.01, y), xycoords=ax.get_yaxis_transform(),
                    xytext=(0, 3), textcoords="offset points", va="bottom", ha="left", color=INK2,
                    fontsize=k(8.5), zorder=5, bbox=dict(facecolor=SURFACE, edgecolor="none", pad=0.6))


def spread_labels(ys, min_gap):
    """Nudge label heights apart so they do not overlap; keeps their order."""
    order = np.argsort(ys)
    placed = list(np.array(ys, dtype=float)[order])
    for i in range(1, len(placed)):
        placed[i] = max(placed[i], placed[i - 1] + min_gap)
    out = np.empty(len(ys))
    out[order] = placed
    return out


def learning_curves(ax, series, bench, band=False, ymax=None, seeds="lines", colours=None, styles=None,
                    legend_loc=("upper left", (0, 1.0))):
    """series: [(label, runs)]. seeds: "lines" (thin line per seed), "band" (min-max band)
    or "none"; the thick line is the mean over seeds."""
    if band:
        seeds = "band"
    ends = []
    for i, (label, runs) in enumerate(series):
        colour = colours[i] if colours else SERIES[i]
        style = styles[i] if styles else "-"
        curves = np.array([blocks(s) for _, s, _ in runs])
        x = np.arange(1, curves.shape[1] + 1) * BLOCK
        if seeds == "band":
            ax.fill_between(x, curves.min(axis=0), curves.max(axis=0), color=colour, alpha=0.18,
                            linewidth=0, zorder=2)
        elif seeds == "lines":
            for c in curves:
                ax.plot(x, c, color=colour, linewidth=k(0.8), alpha=0.35, zorder=2, linestyle=style)
        mean = curves.mean(axis=0)
        ax.plot(x, mean, color=colour, linewidth=k(2.0), zorder=3, label=label, linestyle=style)
        ends.append((x[-1], mean[-1], label, colour))
    # benchmarks: dashed lines, labelled at the right end together with the series
    refs = ("HandCoded", "Random")
    reference_lines(ax, bench, names=refs, label=False)
    xend = ends[0][0]
    ends += [(xend, bench[n], BENCH_LABELS[n], None) for n in refs]
    top = ymax or ax.get_ylim()[1]
    ax.set_ylim(0, top)
    ax.set_xlim(0, xend)
    ys = spread_labels([e[1] for e in ends], min_gap=top * (0.085 if MODE["ieee"] else 0.055))
    for (xe, ye, label, colour), yl in zip(ends, ys):
        if colour:
            ax.plot([xe], [ye], marker="o", markersize=k(5), color=colour, zorder=4, clip_on=False)
        text = label if colour else f"{label}  {ye:.1f} s"  # series: name only; benchmarks: value
        ax.annotate(text, xy=(xe, ye), xytext=(xe + xend * (0.05 if MODE["ieee"] else 0.015), yl),
                    va="center", ha="left", color=INK2 if colour else MUTED, fontsize=k(9),
                    annotation_clip=False)
    ax.set_xticks(np.arange(0, xend + 1, 5000))
    ax.set_xticklabels([f"{int(t / 1000)}k" if t else "0" for t in ax.get_xticks()])
    ax.set_xlabel("Training episodes")
    ax.set_ylabel(f"Possession time (s)\nmean per {BLOCK:,} episodes" if MODE["ieee"]
                  else f"Possession time (s), per-{BLOCK:,}-episode average")
    style_axes(ax)
    if len(series) > 1:
        ncol = len(series) if len(series) <= (2 if MODE["ieee"] else 3) else 2
        if MODE["ieee"]:  # above the plot, clear of the curves
            legend_loc = ("lower left", (-0.02, 1.0))
        ax.legend(loc=legend_loc[0], ncol=ncol, fontsize=k(9), bbox_to_anchor=legend_loc[1],
                  handlelength=1.6 if MODE["ieee"] else 2.0, columnspacing=1.0 if MODE["ieee"] else 2.0)


def window_panels(fig, axes, categories, groups, bench, colours=None, xlabel="", chosen=None):
    """Two panels (first / last 5,000 episodes); one dot per seed, mean joined by a line.
    groups: list of runs, one per category. chosen: category to mark as the decision."""
    stats = [summarize(r) for r in groups]
    windows = [(f"First {EARLY:,} episodes", 0), (f"Last {LATE:,} episodes", 1)]
    x = np.arange(len(categories))
    for ax, (title, win) in zip(axes, windows):
        means = []
        for i, st in enumerate(stats):
            vals = np.array(st[win])
            colour = colours[i] if colours else SERIES[0]
            jitter = np.linspace(-0.08, 0.08, len(vals)) if len(vals) > 1 else [0]
            ax.scatter(x[i] + jitter, vals, s=ka(22), color=colour, alpha=0.45, linewidths=0, zorder=3)
            means.append(vals.mean())
        if not colours:  # a sweep: join the means; separate methods are left unjoined
            ax.plot(x, means, color=SERIES[0], linewidth=k(1.5), zorder=2)
        for i, m in enumerate(means):
            colour = colours[i] if colours else SERIES[0]
            ax.scatter([x[i]], [m], s=ka(70), color=colour, edgecolors=SURFACE, linewidths=k(1.5), zorder=4)
            offset, ha, va = ((k(16), 0), "left", "center") if colours else ((0, k(9)), "center", "bottom")
            ax.annotate(f"{m:.1f}", xy=(x[i], m), xytext=offset, textcoords="offset points",
                        va=va, ha=ha, color=INK, fontsize=k(9) if (colours or not MODE["ieee"]) else 6.2,
                        zorder=5,
                        bbox=dict(facecolor=SURFACE, edgecolor="none", pad=0.5))
        reference_lines(ax, bench, names=("HandCoded",), label=(ax is axes[-1]))
        ax.set_xticks(x)
        ax.set_xticklabels([f"{c}\n(chosen)" if c == chosen else c for c in categories])
        if chosen in categories:
            j = categories.index(chosen)
            ax.axvspan(j - 0.42, j + 0.42, color="#efeee8", zorder=0, linewidth=0)
            ax.get_xticklabels()[j].set_fontweight("semibold")
            ax.get_xticklabels()[j].set_color(INK)
        ax.set_xlim(-0.5, len(categories) - 0.5)
        ax.set_title(title, fontsize=k(10.5), color=INK, loc="left")
        ax.set_xlabel("" if MODE["ieee"] else xlabel)
        style_axes(ax)
    if MODE["ieee"] and xlabel:  # one label for both panels
        fig.supxlabel(xlabel, fontsize=8, color=INK2, y=0.0)
    axes[0].set_ylabel("Average possession time (s)")
    lo = min(min(min(st[0]) for st in stats), bench["HandCoded"]) - 2
    hi = max(max(st[1]) for st in stats) + 2
    axes[0].set_ylim(max(0, lo), hi)


def finish(fig, title, subtitle, path, right=0.95, bottom=0.165):
    if MODE["ieee"]:  # leave room on the right only where end labels sit outside the axes
        save_ieee(fig, path, right=0.72 if right < 0.9 else 0.98, bottom=0.2 if bottom < 0.2 else 0.24)
        return
    fig.text(0.015, 0.955, title, ha="left", va="top", fontsize=13, color=INK, fontweight="semibold")
    fig.text(0.015, 0.885, subtitle, ha="left", va="top", fontsize=9, color=INK2)
    fig.text(0.985, 0.01, "Visualization generated by an LLM (Claude, Anthropic)", ha="right", va="bottom",
             fontsize=7.5, color=MUTED)
    fig.subplots_adjust(left=0.085, right=right, top=0.78, bottom=bottom, wspace=0.08)
    fig.savefig(path, dpi=200)
    plt.close(fig)
    print("wrote", path)


# ---- main -----------------------------------------------------------------------
# Decisions made by Jagjit from the after-fix tuning runs (2026-11-23); marked on the figures.
CHOSEN = {"gamma": "0.99", "tc_alpha": "0.6", "tiles": "20", "rbf_alpha": "0.6", "sigma": "0.01"}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--in", dest="in_dir", default="results/precode-merge-results")
    ap.add_argument("--bench-dir", dest="bench_dir", default="results/prev runs")
    ap.add_argument("--out", dest="out_dir", default=None)
    ap.add_argument("--ieee", action="store_true", help="print-size figures for a two-column IEEE paper")
    args = ap.parse_args()
    if args.ieee:
        set_ieee()
    if args.out_dir is None:
        args.out_dir = "results/figures/ieee" if args.ieee else "results/figures"
    os.makedirs(args.out_dir, exist_ok=True)
    out = lambda name: os.path.join(args.out_dir, name)
    L = lambda prefix: load(args.in_dir, prefix)
    V = lambda prefix: sweep_values(args.in_dir, prefix)
    bench = benchmarks(args.bench_dir)

    gammas, tc_alphas, tiles = V("tc-gamma-tune"), V("tc-alpha-tune"), V("tc-tile-tune")
    rbf_alphas, sigmas = V("rbf-alpha-tune"), V("rbf-sd-tune")
    n_final = len(L("cmp-tc-final"))

    # (case, condition, file prefix)
    table = (
        [("1 TC gamma", f"gamma {g}", f"tc-gamma-tune-{g}") for g in gammas]
        + [("2 TC alpha", f"alpha {a}", f"tc-alpha-tune-{a}") for a in tc_alphas]
        + [("3 TC tiles", f"{t} tiles", f"tc-tile-tune-{t}") for t in tiles]
        + [("4 keepers", "1 learner + 2 hand-coded", "tc-keeper-tune-1"),
           ("4 keepers", "3 learners", "tc-keeper-tune-3")]
        + [("5 RBF alpha", f"alpha {a}", f"rbf-alpha-tune-{a}") for a in rbf_alphas]
        + [("6 RBF sigma", f"sigma {s}", f"rbf-sd-tune-{s}") for s in sigmas]
        + [("7 TC vs RBF, 13 features", "Tile coding", "cmp-tc-final"),
           ("7 TC vs RBF, 13 features", "RBF", "cmp-rbf-final"),
           ("8 TC vs RBF, 4 features", "Tile coding", "cmp-tc-reduced-final"),
           ("8 TC vs RBF, 4 features", "RBF", "cmp-rbf-reduced-final")]
    )
    with open(out("summary.csv"), "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["case", "condition", "seeds",
                    "first5k_mean", "first5k_min", "first5k_max",
                    "last5k_mean", "last5k_min", "last5k_max",
                    f"episodes_to_{int(SPEED_LEVEL)}s_median", f"episodes_to_{int(SPEED_LEVEL)}s_min",
                    f"episodes_to_{int(SPEED_LEVEL)}s_max", "seeds_never_reached", "out_of_bounds_pct"])
        for case, cond, prefix in table:
            e, l, sp, op = summarize(L(prefix))
            reached = [s for s in sp if s is not None]
            w.writerow([case, cond, len(e),
                        f"{np.mean(e):.1f}", f"{min(e):.1f}", f"{max(e):.1f}",
                        f"{np.mean(l):.1f}", f"{min(l):.1f}", f"{max(l):.1f}",
                        int(np.median(reached)) if reached else "", min(reached) if reached else "",
                        max(reached) if reached else "", len(sp) - len(reached), f"{np.mean(op):.2f}"])
        for name in ["HandCoded", "Random", "AlwaysHold"]:
            w.writerow(["benchmark (all 3 keepers)", name, "", "", "", "", f"{bench[name]:.1f}", "", "",
                        "", "", "", "", ""])
    print("wrote", out("summary.csv"))

    tag = lambda v, key: " (chosen)" if v == CHOSEN[key] else ""

    # Fig 1: discount factor
    fig, ax = plt.subplots(figsize=figsize())
    learning_curves(ax, [(f"γ = {g}{tag(g, 'gamma')}", L(f"tc-gamma-tune-{g}")) for g in gammas],
                    bench, ymax=42)
    finish(fig, f"Tile coding: discount factor γ — chosen γ = {CHOSEN['gamma']}",
           "3 learning keepers · α = 0.1 · 10 tiles × 10 tilings · thin lines = 3 seeds, thick = mean",
           out("fig1_tc_gamma.png"), right=0.78)

    # Fig 2: tile-coding alpha
    fig, axes = plt.subplots(1, 2, figsize=figsize(), sharey=True)
    window_panels(fig, axes, tc_alphas, [L(f"tc-alpha-tune-{a}") for a in tc_alphas], bench, xlabel="α",
                  chosen=CHOSEN["tc_alpha"])
    finish(fig, f"Tile coding: step size α — chosen α = {CHOSEN['tc_alpha']}",
           f"3 learning keepers · γ = {CHOSEN['gamma']} · 10 tiles × 10 tilings · small dots = 3 seeds, large = mean",
           out("fig2_tc_alpha.png"), bottom=0.21)

    # Fig 3: tiles
    fig, axes = plt.subplots(1, 2, figsize=figsize(), sharey=True)
    window_panels(fig, axes, tiles, [L(f"tc-tile-tune-{t}") for t in tiles], bench,
                  xlabel="Tiles per tiling (10 tilings)", chosen=CHOSEN["tiles"])
    finish(fig, f"Tile coding: number of tiles — chosen {CHOSEN['tiles']} tiles",
           f"3 learning keepers · γ = {CHOSEN['gamma']} · α = {CHOSEN['tc_alpha']} · small dots = 3 seeds, large = mean",
           out("fig3_tc_tiles.png"), bottom=0.21)

    # Fig 4: one vs three learners
    fig, ax = plt.subplots(figsize=figsize())
    learning_curves(ax, [("1 learner", L("tc-keeper-tune-1")), ("3 learners", L("tc-keeper-tune-3"))],
                    bench, ymax=42)
    finish(fig, "One learning keeper vs three learning keepers",
           f"1 learner = 1 learning + 2 hand-coded keepers · tile coding · γ = {CHOSEN['gamma']} · "
           f"α = {CHOSEN['tc_alpha']} · {CHOSEN['tiles']} tiles × 10 tilings · 3 seeds",
           out("fig4_keepers.png"), right=0.80)

    # Fig 5: RBF alpha
    fig, axes = plt.subplots(1, 2, figsize=figsize(), sharey=True)
    window_panels(fig, axes, rbf_alphas, [L(f"rbf-alpha-tune-{a}") for a in rbf_alphas], bench, xlabel="α",
                  chosen=CHOSEN["rbf_alpha"])
    finish(fig, f"RBF: step size α — chosen α = {CHOSEN['rbf_alpha']}",
           f"3 learning keepers · γ = {CHOSEN['gamma']} · 200 centres · σ = 0.025 · small dots = 3 seeds, large = mean",
           out("fig5_rbf_alpha.png"), bottom=0.21)

    # Fig 6: RBF sigma
    fig, axes = plt.subplots(1, 2, figsize=figsize(), sharey=True)
    window_panels(fig, axes, sigmas, [L(f"rbf-sd-tune-{s}") for s in sigmas], bench,
                  xlabel="σ (centre spacing = 0.005)", chosen=CHOSEN["sigma"])
    finish(fig, f"RBF: Gaussian width σ — chosen σ = {CHOSEN['sigma']}",
           f"3 learning keepers · γ = {CHOSEN['gamma']} · α = {CHOSEN['rbf_alpha']} · 200 centres · "
           "small dots = 3 seeds, large = mean",
           out("fig6_rbf_sigma.png"), bottom=0.21)

    # Fig 7 and 8: TC vs RBF, 13 features
    tc, rbf = L("cmp-tc-final"), L("cmp-rbf-final")
    settings = (f"TC: {CHOSEN['tiles']} tiles × 10 tilings, α = {CHOSEN['tc_alpha']} · "
                f"RBF: 200 centres, σ = {CHOSEN['sigma']}, α = {CHOSEN['rbf_alpha']}")
    fig, ax = plt.subplots(figsize=figsize())
    learning_curves(ax, [("Tile coding", tc), ("RBF", rbf)], bench, band=True, ymax=48)
    finish(fig, "Tile coding vs RBF (13 features)",
           f"γ = {CHOSEN['gamma']} · {settings} · band = range of {n_final} seeds",
           out("fig7_tc_vs_rbf_curves.png"), right=0.80)
    fig, axes = plt.subplots(1, 2, figsize=figsize("full"), sharey=True)
    window_panels(fig, axes, ["Tile coding", "RBF"], [tc, rbf], bench, colours=SERIES[:2])
    finish(fig, "Tile coding vs RBF (13 features): early learning and final level",
           f"Same runs as the learning curves · small dots = {n_final} seeds, large = mean",
           out("fig8_tc_vs_rbf_windows.png"), bottom=0.21)

    # Fig 9: reduced (4) vs full (13) features
    tcr, rbfr = L("cmp-tc-reduced-final"), L("cmp-rbf-reduced-final")
    fig, ax = plt.subplots(figsize=figsize())
    learning_curves(ax, [("TC, 13 features", tc), ("RBF, 13 features", rbf),
                         ("TC, 4 features", tcr), ("RBF, 4 features", rbfr)], bench, ymax=42, seeds="none",
                    colours=[SERIES[0], SERIES[1], SERIES[0], SERIES[1]], styles=["-", "-", "--", "--"],
                    legend_loc=("lower center", (0.5, 0.3)))
    finish(fig, "Reduced (4) vs full (13) state variables",
           f"γ = {CHOSEN['gamma']} · same settings as case 7 · lines = mean of {n_final} seeds",
           out("fig9_reduced_vs_full.png"), right=0.78)


if __name__ == "__main__":
    main()
